                    </div>
                </button>
                <span class="text-sm text-[#7f5e53]">Sort by</span>                <select (change)="sortProducts($any($event.target).value)" class="form-select text-sm text-[#1b120e] font-medium border-[#eb6c28] rounded-md focus:ring-2 focus:ring-[#eb6c28] focus:border-transparent">
                    <option value="popularity">Popularity</option>
                    <option value="price-low-high">Price: Low to High</option>
                    <option value="price-high-low">Price: High to Low</option>
                    <option value="newest">Newest</option>
                </select>
            </div>
            <div class="flex items-center gap-2">
                <span class="text-sm text-[#7f5e53]">Filter by Brand:</span>
                <select (change)="filterByBrand($any($event.target).value)" class="form-select text-sm text-[#1b120e] font-medium border-[#eb6c28] rounded-md focus:ring-2 focus:ring-[#eb6c28] focus:border-transparent">
                    <option value="">All Brands</option>
                    <option *ngFor="let brand of brands" [value]="brand" [selected]="selectedBrand === brand">{{ brand }}</option>
                </select>
            </div>
        </div>
        
        <!-- Loading indicator -->
        <div *ngIf="loading" class="flex justify-center py-8">
            <div class="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#eb6c28]"></div>
        </div>
          <!-- Error message -->
        <div *ngIf="error" class="text-red-500 text-center py-4">
            {{ error }}
        </div>
        
        <!-- Empty state -->
        <div *ngIf="!loading && !error && filteredProducts.length === 0" class="flex flex-col items-center justify-center py-12">
            <div class="bg-gray-100 rounded-full p-6 mb-4">
                <svg xmlns="http://www.w3.org/2000/svg" class="h-12 w-12 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
            </div>
            <h3 class="text-xl font-semibold text-gray-700 mb-2">No Products Found</h3>
            <p class="text-gray-500 text-center mb-6 max-w-md">We couldn't find any products matching your criteria. Please try a different filter or check back later.</p>
            <button (click)="filterByBrand('')" class="px-4 py-2 bg-[#eb6c28] text-white rounded-lg hover:bg-[#d95f21] transition-colors">
                View All Products
            </button>
        </div>
        <div class="grid grid-cols-[repeat(auto-fit,minmax(220px,1fr))] gap-6 p-4">
            <!-- API products -->
            <div *ngFor="let product of filteredProducts" class="flex flex-col gap-4 pb-4 rounded-xl overflow-hidden shadow-sm hover:shadow-lg transition-shadow duration-300 bg-white">
                <a class="block overflow-hidden" [routerLink]="['/product-detail']" [queryParams]="{name: product.name}">
                    <div class="w-full bg-center bg-no-repeat aspect-[4/3] bg-cover"
                         [style.background-image]="'url(' + product.imageLink + ')'"></div>
                </a>                <div class="px-4 flex flex-col flex-grow">
                    <a class="block text-[#1b120e] text-lg font-semibold leading-normal hover:text-[#eb6c28] transition-colors"
                       [routerLink]="['/product-detail']" [queryParams]="{name: product.name}">{{ product.name }}</a>
                    <p class="text-[#7f5e53] text-sm font-normal leading-normal mt-1 flex-grow">{{ product.brandName }}</p>
                    <p class="text-[#eb6c28] text-base font-bold leading-normal mt-2">{{ product.price | currency:'VND':'symbol':'1.0-0' }}</p>
                </div>
                <div class="px-4 mt-auto flex flex-col sm:flex-row gap-2">
                    <button (click)="addToCart(product)"
                            class="flex-1 whitespace-nowrap text-sm font-medium leading-normal text-[#1b120e] bg-transparent border border-[#eb6c28] hover:bg-[#fef5f0] rounded-md px-3 py-2 transition-colors">
                        Add to Cart
                    </button>
                    <button (click)="buyNow(product)"
                            class="flex-1 whitespace-nowrap text-sm font-medium leading-normal text-white bg-[#eb6c28] hover:bg-[#d95f21] rounded-md px-3 py-2 transition-colors">
                        Buy Now
                    </button>
                </div>
            </div>
        </div> <!-- grid container -->
    </div>
</div>
